import{_ as o,o as i,c as r,a2 as e,j as a,a as s,t as l}from"./chunks/framework.DYYBR_aZ.js";const d="/tech-notes/assets/postman-raw%E9%80%89%E9%A1%B9.ClpT2k5M.png",y=JSON.parse('{"title":"Postman的使用","description":"","frontmatter":{},"headers":[],"relativePath":"tools/Postman的使用.md","filePath":"tools/Postman的使用.md"}'),p={name:"tools/Postman的使用.md"};function c(n,t,g,h,u,k){return i(),r("div",null,[t[2]||(t[2]=e('<h1 id="postman的使用" tabindex="-1">Postman的使用 <a class="header-anchor" href="#postman的使用" aria-label="Permalink to &quot;Postman的使用&quot;">​</a></h1><h2 id="raw的介绍" tabindex="-1">raw的介绍 <a class="header-anchor" href="#raw的介绍" aria-label="Permalink to &quot;raw的介绍&quot;">​</a></h2><p>postman的请求设置里，body中有个raw选项；</p><ul><li><strong>其他选项（如 <code>x-www-form-urlencoded</code>）</strong>：Postman 会帮你把数据自动包装成类似 <code>username=admin&amp;pwd=123</code> 这种浏览器表单的标准格式。</li><li><strong>raw 选项</strong>：表示你不想让 Postman 帮忙转换，而是要<strong>把一段“原汁原味”的原始字符串直接发送给服务器</strong>。</li></ul><p>选中 <code>raw</code> 后，旁边会弹出一个下拉菜单。你需要点击那个下拉菜单，选择具体的数据类型，最常用的就是 <strong>JSON</strong>。</p><p><img src="'+d+`" alt="Postman raw 选项"></p><p>如果你选择 <code>raw</code> -&gt; <code>JSON</code>，Postman 就会自动帮你添加请求头 <code>Content-Type: application/json</code>，然后你就可以在下面的编辑框里，直接粘贴最纯粹的 JSON 文本：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;username&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;admin&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;pwd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;123&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>总结：其实选择raw-&gt;json后，postman帮我们做的只有： 自动帮我们加上 Content-Type: application/json 这个请求头</strong></p><h2 id="postman中的常规操作" tabindex="-1">postman中的常规操作 <a class="header-anchor" href="#postman中的常规操作" aria-label="Permalink to &quot;postman中的常规操作&quot;">​</a></h2><ol><li><strong>URL 栏</strong>：填入 <code>https://www.example.com/api/login</code>（Host 自动出来）</li><li><strong>Method</strong>：选择 <code>POST</code></li><li><strong>Body 标签页</strong>：选择 <code>raw</code> → <code>JSON</code>，然后粘贴 <code>{&quot;username&quot;: &quot;admin&quot;, &quot;pwd&quot;: &quot;123&quot;}</code>（Content-Type 和 Content-Length 自动加上）</li><li><strong>Headers 标签页</strong>：一般留空即可。除非你要传自定义头（比如 <code>Authorization: Bearer xxx</code>），才需要手动加</li></ol><h2 id="几个选项" tabindex="-1">几个选项： <a class="header-anchor" href="#几个选项" aria-label="Permalink to &quot;几个选项：&quot;">​</a></h2><ul><li><strong><code>Params</code></strong>：最终会组合进 <strong>请求行（URL）</strong> 中。</li><li><strong><code>Authorization</code></strong>：本质上属于 <strong>请求头（Headers）</strong>。</li><li><strong><code>Headers (6)</code></strong>：属于 <strong>请求头（Headers）</strong>。</li></ul><p><strong>关于 Params 和 URL 的关系：两者完全可以二选一</strong></p><p><strong><code>Params</code> 选项卡里填写的键值对，本质上就是可以直接写在 URL 里的查询参数（Query String）</strong>。</p><p><strong>方式一：在 <code>Params</code> 选项卡中填写</strong> 在 Key 和 Value 栏里分别填入 <code>page</code> 和 <code>1</code>，<code>limit</code> 和 <code>10</code>。</p><p><strong>方式二：直接写在 URL 中</strong> 在地址栏里直接手动输入： <code>https://www.example.com/api/getdata?page=1&amp;limit=10</code></p><p><strong>无论你用哪种方式，Postman 在最终发送请求时，拼出来的 HTTP 请求行是完全一模一样的。</strong></p><p>怎么选择呢：</p><ul><li>使用 <code>Params</code> 选项卡（推荐） <ul><li><strong>参数很多、很长的时候，写在 URL 里非常乱，容易把 <code>?</code>、<code>&amp;</code> 符号打错。</strong></li><li><strong>在选项卡里像 Excel 一样一行一行地写，清晰、方便修改，还不容易出错。</strong></li><li><strong>支持一键隐藏（Disable）某些参数，调试时非常方便。</strong></li></ul></li><li>直接写在 URL 中 <ul><li>参数很少（比如就一两个），直接拼在链接里更直观。</li><li>当你复制一段完整的 API 链接时，直接粘贴进去最快。</li></ul></li></ul><h2 id="postman中的变量" tabindex="-1">postman中的变量 <a class="header-anchor" href="#postman中的变量" aria-label="Permalink to &quot;postman中的变量&quot;">​</a></h2><h3 id="postman-常见变量类型" tabindex="-1"><strong>Postman 常见变量类型</strong> <a class="header-anchor" href="#postman-常见变量类型" aria-label="Permalink to &quot;**Postman 常见变量类型**&quot;">​</a></h3><p><strong>多个请求共享同一组服务器地址和认证信息，优先用「环境变量」；</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">变量类型</th><th style="text-align:center;">作用域</th><th style="text-align:center;">适合放什么</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>全局变量 Global</strong></td><td style="text-align:center;">整个工作空间</td><td style="text-align:center;">临时调试值；团队场景下慎用</td></tr><tr><td style="text-align:center;"><strong>集合变量 Collection</strong></td><td style="text-align:center;">当前集合内</td><td style="text-align:center;">集合内通用配置，如 API 版本、默认路径</td></tr><tr><td style="text-align:center;"><strong>环境变量 Environment</strong></td><td style="text-align:center;">当前环境</td><td style="text-align:center;"><code>base_url</code>、token、tenantId 等环境相关配置</td></tr><tr><td style="text-align:center;"><strong>数据变量 Data</strong></td><td style="text-align:center;">一次集合运行</td><td style="text-align:center;">CSV/JSON 导入的批量测试数据</td></tr><tr><td style="text-align:center;"><strong>局部变量 Local</strong></td><td style="text-align:center;">当前请求/本次运行</td><td style="text-align:center;">脚本里临时算出来的值，不持久化</td></tr></tbody></table><h3 id="使用方式" tabindex="-1">使用方式 <a class="header-anchor" href="#使用方式" aria-label="Permalink to &quot;使用方式&quot;">​</a></h3><h3 id="_1-新建环境" tabindex="-1"><strong>1. 新建环境</strong> <a class="header-anchor" href="#_1-新建环境" aria-label="Permalink to &quot;**1. 新建环境**&quot;">​</a></h3><p>打开 Postman 桌面客户端后：</p><ol><li>点击左侧栏的 <strong>Environments</strong>；</li><li>点击 <strong>Add</strong> / <strong>+</strong> 新建一个环境；</li><li>输入环境名称，比如 <code>dev</code>、<code>test</code>、<code>prod</code>；</li><li>点击 <strong>Save</strong>。</li></ol><p>也可以点右上角的 <strong>环境选择器 / 齿轮图标</strong>，选择 <strong>Manage Environments</strong>，再点 <strong>Add</strong> 创建。</p><h3 id="_2-添加变量" tabindex="-1"><strong>2. 添加变量</strong> <a class="header-anchor" href="#_2-添加变量" aria-label="Permalink to &quot;**2. 添加变量**&quot;">​</a></h3><p>进入刚才创建的环境后，添加变量：</p><table tabindex="0"><thead><tr><th style="text-align:center;">字段</th><th style="text-align:center;">填什么</th><th style="text-align:center;">示例</th></tr></thead><tbody><tr><td style="text-align:center;">Variable</td><td style="text-align:center;">变量名</td><td style="text-align:center;"><code>base_url</code></td></tr><tr><td style="text-align:center;">Initial value</td><td style="text-align:center;">初始值，适合团队共享</td><td style="text-align:center;"><code>https://api.example.com</code></td></tr><tr><td style="text-align:center;">Current value</td><td style="text-align:center;">当前值，本地生效</td><td style="text-align:center;"><code>https://api.dev.example.com</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Variable: base_url</span></span>
<span class="line"><span>Initial value: https://api.example.com</span></span></code></pre></div><p>如果变量是敏感信息，比如 <code>token</code>、<code>api_key</code>，可以把它标记为 <strong>sensitive</strong>。</p><h3 id="_3-选中环境" tabindex="-1"><strong>3. 选中环境</strong> <a class="header-anchor" href="#_3-选中环境" aria-label="Permalink to &quot;**3. 选中环境**&quot;">​</a></h3><p>回到 Postman 右上角的 <strong>环境选择器</strong>，把当前环境切换成你刚建好的环境，例如 <code>dev</code>。</p><p>这一步很重要：<strong>不选中环境，环境变量不会生效。</strong></p><h3 id="_4-在请求中引用" tabindex="-1"><strong>4. 在请求中引用</strong> <a class="header-anchor" href="#_4-在请求中引用" aria-label="Permalink to &quot;**4. 在请求中引用**&quot;">​</a></h3><p>在 URL、Headers、Body、Params 里都可以用双花括号引用：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{{base_url}}/api/login</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer {{token}}</span></span></code></pre></div>`,41)),a("p",null,[t[0]||(t[0]=s("Postman 发送请求时，会自动把 ",-1)),a("code",null,l(n.base_url),1),t[1]||(t[1]=s(" 替换成当前环境里对应的值。",-1))]),t[3]||(t[3]=e(`<h3 id="_5-用脚本动态设置" tabindex="-1"><strong>5. 用脚本动态设置</strong> <a class="header-anchor" href="#_5-用脚本动态设置" aria-label="Permalink to &quot;**5. 用脚本动态设置**&quot;">​</a></h3><p>如果你想在登录接口返回后自动保存 token，可以在 <strong>Tests</strong> 脚本里写：</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> res</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pm.response.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">json</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pm.environment.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, res.data.token);</span></span></code></pre></div><p>这样后续请求只要写：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer {{token}}</span></span></code></pre></div><p>就能自动带上最新 token。</p>`,6))])}const b=o(p,[["render",c]]);export{y as __pageData,b as default};
